#!/usr/bin/env node
/**
 * Google Drive access for agents — read-only, signed in as a real user.
 *
 * An API key is an anonymous caller: it reaches only "anyone with the link"
 * files and answers 403 insufficientFilePermissions to any listing. Folders
 * shared with the Brandklout account need that account's identity, so this
 * uses an OAuth "Desktop app" client (loopback redirect + PKCE) and keeps the
 * refresh token in the MASTER credential file, never in a worktree .env —
 * those are regenerated by env-sync.mjs and would lose it.
 *
 *   node scripts/drive.mjs auth                    one-time browser sign-in
 *   node scripts/drive.mjs whoami                  which account the token is
 *   node scripts/drive.mjs search <text> [--folders]   name contains <text>
 *   node scripts/drive.mjs ls <folder id|url>      list a folder's children
 *   node scripts/drive.mjs get <file id|url> [dir]     download one file
 *   node scripts/drive.mjs pull <folder id|url> <dir>  download a folder tree
 *
 * Credentials (process.env, then ~/.webzite/.env [shared], then the nearest .env):
 *   GOOGLEDRIVEOAUTHID   client ID
 *   GOOGLEDRIVEOAUTH     client secret
 *   GOOGLEDRIVEREFRESH   written by `auth`
 *
 * While the consent screen is in "Testing", Google expires the refresh token
 * after 7 days; `invalid_grant` means run `auth` again.
 *
 * Google Docs/Sheets/Slides/Drawings have no bytes of their own and are
 * exported (docx/xlsx/pdf/png). Shared drives are included everywhere.
 *
 * This tool never prints a credential value.
 */

import fs from 'node:fs'
import os from 'node:os'
import path from 'node:path'
import crypto from 'node:crypto'
import { createServer } from 'node:http'
import { execFile } from 'node:child_process'
import { Readable } from 'node:stream'
import { pipeline } from 'node:stream/promises'

const MASTER = process.env.WEBZITE_ENV_MASTER || path.join(os.homedir(), '.webzite', '.env')
const SCOPE = 'https://www.googleapis.com/auth/drive.readonly'
const API = 'https://www.googleapis.com/drive/v3'
const FOLDER = 'application/vnd.google-apps.folder'
const EXPORTS = {
  'application/vnd.google-apps.document': ['application/vnd.openxmlformats-officedocument.wordprocessingml.document', '.docx'],
  'application/vnd.google-apps.spreadsheet': ['application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', '.xlsx'],
  'application/vnd.google-apps.presentation': ['application/pdf', '.pdf'],
  'application/vnd.google-apps.drawing': ['image/png', '.png'],
}

function parseEnv (file, section) {
  const out = {}
  if (!fs.existsSync(file)) return out
  let current = null
  for (const line of fs.readFileSync(file, 'utf8').split(/\r?\n/)) {
    const s = line.match(/^\s*\[([^\]]+)\]\s*$/)
    if (s) { current = s[1].trim(); continue }
    if (section && current !== section) continue
    const m = line.match(/^([A-Za-z_][A-Za-z0-9_]*)=(.*)$/)
    if (m) out[m[1]] = m[2].trim().replace(/^["']|["']$/g, '')
  }
  return out
}

function nearestEnv () {
  for (let dir = process.cwd(); ; dir = path.dirname(dir)) {
    const f = path.join(dir, '.env')
    if (fs.existsSync(f) && path.resolve(f) !== path.resolve(MASTER)) return f
    if (path.dirname(dir) === dir) return null
  }
}

// The master wins over a worktree .env: a generated copy can be stale (auth
// writes the refresh token to the master only). The .env is the fallback for
// machines that have no master.
function creds () {
  const local = nearestEnv()
  const merged = { ...(local ? parseEnv(local) : {}), ...parseEnv(MASTER, 'shared') }
  for (const k of ['GOOGLEDRIVEOAUTHID', 'GOOGLEDRIVEOAUTH', 'GOOGLEDRIVEREFRESH']) {
    if (process.env[k]) merged[k] = process.env[k]
  }
  return merged
}

function need (c, ...keys) {
  const missing = keys.filter(k => !c[k])
  if (!missing.length) return
  console.error(`Missing: ${missing.join(', ')} (add to [shared] in ${MASTER}).`)
  if (missing.includes('GOOGLEDRIVEREFRESH')) console.error('Run `node scripts/drive.mjs auth` first.')
  process.exit(1)
}

// Replaces or inserts one key inside [shared] of the master, leaving every
// other line — comments, other sections, line endings — untouched.
function setShared (key, value) {
  const raw = fs.readFileSync(MASTER, 'utf8')
  const eol = raw.includes('\r\n') ? '\r\n' : '\n'
  const lines = raw.split(/\r?\n/)
  const start = lines.findIndex(l => /^\s*\[shared\]\s*$/.test(l))
  if (start < 0) throw new Error(`No [shared] section in ${MASTER}`)
  let end = lines.findIndex((l, i) => i > start && /^\s*\[[^\]]+\]\s*$/.test(l))
  if (end < 0) end = lines.length
  const existing = lines.findIndex((l, i) => i > start && i < end && l.startsWith(`${key}=`))
  if (existing >= 0) {
    lines[existing] = `${key}=${value}`
  } else {
    let at = end
    for (let i = start; i < end; i++) if (lines[i].startsWith('GOOGLEDRIVE')) at = i + 1
    if (at === end) while (at > start + 1 && lines[at - 1].trim() === '') at--
    lines.splice(at, 0, `${key}=${value}`)
  }
  fs.writeFileSync(MASTER, lines.join(eol))
}

function openBrowser (url) {
  const [cmd, args] = process.platform === 'win32'
    ? ['rundll32', ['url.dll,FileProtocolHandler', url]]
    : [process.platform === 'darwin' ? 'open' : 'xdg-open', [url]]
  execFile(cmd, args, () => {})
}

async function tokenRequest (params) {
  const r = await fetch('https://oauth2.googleapis.com/token', {
    method: 'POST',
    headers: { 'content-type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams(params),
  })
  const j = await r.json()
  if (!r.ok) {
    const hint = j.error === 'invalid_grant'
      ? '\nThe sign-in expired or was revoked (Testing apps expire after 7 days). Run `node scripts/drive.mjs auth`.'
      : ''
    throw new Error(`Token request failed: ${j.error} ${j.error_description || ''}${hint}`)
  }
  return j
}

async function auth () {
  const c = creds()
  need(c, 'GOOGLEDRIVEOAUTHID', 'GOOGLEDRIVEOAUTH')
  const verifier = crypto.randomBytes(48).toString('base64url')
  const challenge = crypto.createHash('sha256').update(verifier).digest('base64url')
  const state = crypto.randomBytes(16).toString('hex')

  const server = createServer()
  await new Promise(resolve => server.listen(0, '127.0.0.1', resolve))
  const redirect = `http://127.0.0.1:${server.address().port}`

  const url = 'https://accounts.google.com/o/oauth2/v2/auth?' + new URLSearchParams({
    client_id: c.GOOGLEDRIVEOAUTHID,
    redirect_uri: redirect,
    response_type: 'code',
    scope: SCOPE,
    access_type: 'offline',
    prompt: 'consent',
    code_challenge: challenge,
    code_challenge_method: 'S256',
    state,
  })

  const code = await new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error('No sign-in within 5 minutes.')), 5 * 60_000)
    server.on('request', (req, res) => {
      const q = new URL(req.url, redirect).searchParams
      if (!q.has('code') && !q.has('error')) { res.writeHead(404).end(); return }
      const ok = q.get('state') === state && q.has('code')
      res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' })
      res.end(ok ? '<h2>Drive connected. You can close this tab.</h2>' : `<h2>Sign-in failed: ${q.get('error') || 'state mismatch'}</h2>`)
      clearTimeout(timer)
      ok ? resolve(q.get('code')) : reject(new Error(`Sign-in failed: ${q.get('error') || 'state mismatch'}`))
    })
    console.log('Opening the Google sign-in page. If nothing opens, visit:\n\n' + url + '\n')
    openBrowser(url)
  }).finally(() => server.close())

  const t = await tokenRequest({
    client_id: c.GOOGLEDRIVEOAUTHID,
    client_secret: c.GOOGLEDRIVEOAUTH,
    code,
    code_verifier: verifier,
    grant_type: 'authorization_code',
    redirect_uri: redirect,
  })
  if (!t.refresh_token) throw new Error('Google returned no refresh token. Remove the app at myaccount.google.com/permissions and run auth again.')
  setShared('GOOGLEDRIVEREFRESH', t.refresh_token)
  console.log(`Saved GOOGLEDRIVEREFRESH to [shared] in ${MASTER}.`)
  console.log('Run `node scripts/env-sync.mjs` in any worktree that should carry it in its .env.')
  await whoami(t.access_token)
}

let cachedToken = null
async function accessToken () {
  if (cachedToken && cachedToken.expires > Date.now() + 60_000) return cachedToken.value
  const c = creds()
  need(c, 'GOOGLEDRIVEOAUTHID', 'GOOGLEDRIVEOAUTH', 'GOOGLEDRIVEREFRESH')
  const t = await tokenRequest({
    client_id: c.GOOGLEDRIVEOAUTHID,
    client_secret: c.GOOGLEDRIVEOAUTH,
    refresh_token: c.GOOGLEDRIVEREFRESH,
    grant_type: 'refresh_token',
  })
  cachedToken = { value: t.access_token, expires: Date.now() + t.expires_in * 1000 }
  return cachedToken.value
}

async function api (pathname, params = {}, raw = false) {
  const url = `${API}${pathname}?` + new URLSearchParams({ supportsAllDrives: 'true', ...params })
  const r = await fetch(url, { headers: { authorization: `Bearer ${await accessToken()}` } })
  if (!r.ok) throw new Error(`Drive ${r.status} on ${pathname}: ${(await r.text()).slice(0, 300)}`)
  return raw ? r : r.json()
}

// Accepts a bare id or any Drive/Docs URL shape.
function idOf (input) {
  if (!input) throw new Error('Missing a Drive id or URL.')
  const m = input.match(/\/folders\/([\w-]+)/) || input.match(/\/d\/([\w-]+)/) || input.match(/[?&]id=([\w-]+)/)
  return m ? m[1] : input
}

async function listChildren (folderId) {
  const files = []
  let pageToken
  do {
    const j = await api('/files', {
      q: `'${folderId}' in parents and trashed = false`,
      fields: 'nextPageToken, files(id, name, mimeType, size, modifiedTime)',
      includeItemsFromAllDrives: 'true',
      corpora: 'allDrives',
      orderBy: 'folder,name',
      pageSize: '1000',
      ...(pageToken ? { pageToken } : {}),
    })
    files.push(...j.files)
    pageToken = j.nextPageToken
  } while (pageToken)
  return files
}

function row (f) {
  const kind = f.mimeType === FOLDER ? 'folder' : f.mimeType.replace(/^application\/(vnd\.google-apps\.)?/, '')
  const size = f.size ? `${Math.round(f.size / 1024)} KB` : ''
  return [f.id, kind.padEnd(14), size.padStart(9), f.name].join('  ')
}

async function whoami (token) {
  const r = await fetch(`${API}/about?fields=user(emailAddress,displayName)`, {
    headers: { authorization: `Bearer ${token || await accessToken()}` },
  })
  const j = await r.json()
  if (!r.ok) throw new Error(`Drive ${r.status}: ${JSON.stringify(j).slice(0, 300)}`)
  console.log(`Signed in as ${j.user.displayName} <${j.user.emailAddress}>`)
}

async function search (text, foldersOnly) {
  const q = [`name contains '${text.replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`, 'trashed = false']
  if (foldersOnly) q.push(`mimeType = '${FOLDER}'`)
  const j = await api('/files', {
    q: q.join(' and '),
    fields: 'files(id, name, mimeType, size, modifiedTime)',
    includeItemsFromAllDrives: 'true',
    corpora: 'allDrives',
    pageSize: '100',
  })
  j.files.forEach(f => console.log(row(f)))
  if (!j.files.length) console.log('No matches.')
}

function safeName (name) {
  return name.replace(/[<>:"/\\|?*␀-]/g, '_').replace(/[. ]+$/, '') || '_'
}

async function download (file, dir) {
  fs.mkdirSync(dir, { recursive: true })
  const exp = EXPORTS[file.mimeType]
  if (file.mimeType.startsWith('application/vnd.google-apps.') && !exp) {
    console.log(`skip  ${file.name} (${file.mimeType} cannot be exported)`)
    return
  }
  const res = exp
    ? await api(`/files/${file.id}/export`, { mimeType: exp[0] }, true)
    : await api(`/files/${file.id}`, { alt: 'media' }, true)
  let name = safeName(file.name)
  if (exp && !name.toLowerCase().endsWith(exp[1])) name += exp[1]
  const out = path.join(dir, name)
  await pipeline(Readable.fromWeb(res.body), fs.createWriteStream(out))
  console.log(`saved ${out}`)
}

async function pull (folderId, dir) {
  for (const f of await listChildren(folderId)) {
    if (f.mimeType === FOLDER) await pull(f.id, path.join(dir, safeName(f.name)))
    else await download(f, dir)
  }
}

const [cmd, ...args] = process.argv.slice(2)
const commands = {
  auth: () => auth(),
  whoami: () => whoami(),
  search: () => search(args.filter(a => a !== '--folders').join(' '), args.includes('--folders')),
  ls: async () => (await listChildren(idOf(args[0]))).forEach(f => console.log(row(f))),
  get: async () => download(await api(`/files/${idOf(args[0])}`, { fields: 'id, name, mimeType' }), args[1] || '.'),
  pull: () => {
    if (!args[1]) throw new Error('pull needs a destination directory.')
    return pull(idOf(args[0]), args[1])
  },
}

if (!commands[cmd]) {
  console.log('Usage: node scripts/drive.mjs <auth|whoami|search|ls|get|pull> ...  (see the header of this file)')
  process.exit(cmd ? 1 : 0)
}
commands[cmd]().catch(err => { console.error(err.message); process.exit(1) })
